def repeat(n):
    def decorate(f):
        def wrapper():
            return [f() for _ in range(n)]
        return wrapper
    return decorate

@repeat
def one():
    return 1

print(one.__name__)

def tag(t):
    def deco(f):
        print('wrap', t)
        return f
    return deco

@tag('top')
@tag('bottom')
def f(): pass

from contextlib import contextmanager
@contextmanager
def tag():
    print('<')
    yield
    print('>')
try:
    with tag():
        raise KeyError
except KeyError:
    print('caught')

try:
